<?php
namespace App\Application\Documentos;
use App\Application\Autorizacion\AutorizacionContextual; use App\Application\Contexto\ContextoOperativo; use App\Models\{Documento,DocumentoVersion,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class AprobarVersionDocumento { public function __construct(private readonly AutorizacionContextual $a,private readonly ConsultaDocumentosContextuales $q,private readonly RegistrarActuacionDocumento $h){} public function ejecutar(ContextoOperativo $c,User $u,Documento $d,DocumentoVersion $v,string $desde,?string $hasta=null):void{$d=$this->q->resolver($c,$d->id);$v=$this->q->resolverVersion($c,$d,$v->id);if(!$this->a->tienePermiso($c,'documentos.aprobar'))throw new AuthorizationException();DB::transaction(function()use($d,$v,$u,$desde,$hasta){$d=Documento::query()->whereKey($d->id)->lockForUpdate()->firstOrFail();$v=DocumentoVersion::query()->whereKey($v->id)->lockForUpdate()->firstOrFail();if($v->estado->value!=='pendiente_aprobacion')throw ValidationException::withMessages(['version'=>['Solo se puede aprobar una Versión pendiente.']]);$anterior=$v->sustituye_version_id?DocumentoVersion::query()->whereKey($v->sustituye_version_id)->where('documento_id',$d->id)->lockForUpdate()->firstOrFail():null;if($anterior&&$anterior->estado->value!=='aprobada')throw ValidationException::withMessages(['sustituye_version_id'=>['La Versión sustituida debe estar aprobada.']]);if($anterior&&$anterior->vigente_desde&&$desde<=$anterior->vigente_desde->toDateString())throw ValidationException::withMessages(['vigente_desde'=>['La sucesora debe iniciar después de la Versión sustituida.']]);$solapa=DocumentoVersion::query()->where('documento_id',$d->id)->where('estado','aprobada')->whereKeyNot($v->id)->when($anterior,fn($q)=>$q->whereKeyNot($anterior->id))->where(fn($q)=>$q->whereNull('vigente_hasta')->orWhere('vigente_hasta','>=',$desde))->where(fn($q)=>$q->whereNull('vigente_desde')->orWhere('vigente_desde','<=',$hasta??'9999-12-31'))->exists();if($solapa)throw ValidationException::withMessages(['vigente_desde'=>['La vigencia se superpone con una Versión aprobada.']]);if($anterior)$anterior->update(['vigente_hasta'=>date('Y-m-d',strtotime($desde.' -1 day'))]);$v->update(['estado'=>'aprobada','vigente_desde'=>$desde,'vigente_hasta'=>$hasta,'aprobada_por_user_id'=>$u->id,'nombre_aprobador'=>$u->name,'aprobada_at'=>now()]);$this->h->registrar($d,$v,$u,'version_aprobada','Aprobó la Versión.');if($anterior)$this->h->registrar($d,$anterior,$u,'vigencia_cerrada','Cerró la vigencia de la Versión sustituida.');});}}
